INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-2', 'Do all invoices include Bahrain NBR 10% VAT and Arabic breakdown?', 'هل تشمل الفواتير ضريبة القيمة المضافة 10% والتفصيل باللغتين؟', 'Yes. Every tax invoice is issued in BHD under CR CR-141022-3 and VAT ID 200014102200002 with itemized bilingual lines.', 'نعم، تصدر جميع الفواتير الضريبية بعملة BHD وفق السجل CR-141022-3 والرقم الضريبي 200014102200002.', 'billing', true, 2, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
