INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-11', 'meridian-advisory-sustainability-pledge', 'Practical Sustainability Targets for Bahrain Operations in 2026', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026', 'Key operational benchmarks, real metrics, and 2026 guidance from Meridian Advisory in Diplomatic Area.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من ميريديان للاستشارات في Diplomatic Area.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Management and financial consultancy advising family conglomerates and growth-stage companies on restructuring, VAT compliance, and expansion. Focusing on Internal Controls & Risk Review, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شركة استشارات إدارية ومالية تدعم المجموعات العائلية والشركات النامية في إعادة الهيكلة والامتثال الضريبي والتوسع. من خلال خدمة مراجعة الضوابط الداخلية والمخاطر نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Management and financial consultancy advising family conglomerates and growth-stage companies on restructuring, VAT compliance, and expansion.</p><p>Focusing on <strong>Internal Controls & Risk Review</strong>, our Diplomatic Area specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>شركة استشارات إدارية ومالية تدعم المجموعات العائلية والشركات النامية في إعادة الهيكلة والامتثال الضريبي والتوسع.</p><p>من خلال خدمة <strong>مراجعة الضوابط الداخلية والمخاطر</strong>، يعمل فريقنا في Diplomatic Area على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Practical Sustainability Targets for Bahrain Operations in 2026 | Meridian Advisory', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026 | ميريديان للاستشارات', 'Executive guide by Meridian Advisory covering Internal Controls & Risk Review benchmarks in Bahrain.', 'دليل تنفيذي من ميريديان للاستشارات حول معايير مراجعة الضوابط الداخلية والمخاطر في البحرين.', 'Sustainability', '{"services","sustainability","Diplomatic Area","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '66 days', false, now() - interval '66 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-11', 'Can scope adjustments be added mid-project cleanly?', 'هل يمكن إضافة أو تعديل نطاق العمل أثناء تنفيذ المشروع؟', 'Any variation order generates a transparent delta quotation linked directly to the parent project and budget.', 'يتم إصدار ملحق تعديل واضح مرتبط مباشرة بميزانية المشروع الأساسية وموافقتكم.', 'changes', true, 11, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
